475	@@ -0,0 +1,148 @@
476	+import '../../../../core/failure/failure.dart';
477	+
478	+/// spec-7-1 — the export job's own progress, modeled as its own sealed
479	+/// domain entity (AD-12: never force `status`+`narrativeStatus` into
480	+/// `Resource<T>`), mirroring `BookmarkState`'s own shape: sealed, with
481	+/// `const factory` constructors declared on the base class so call sites
482	+/// read as `ExportJobState.preparing()` rather than naming each subclass
483	+/// directly. Exactly the 5 states `docs/input/backend/export-screen-
484	+/// states.md`'s own status×narrativeStatus×downloadAvailable table
485	+/// collapses into (`data_ready` folds into [ExportJobState.generating],
486	+/// Design Notes — no case of its own here).
487	+///
488	+/// Never persisted (AD-15: ephemeral, polled live) — lives only on
489	+/// `ExportJobCubit.state`.
490	+sealed class ExportJobState {
491	+  const ExportJobState();
492	+
493	+  /// `status: 'pending'` — spinner, "Preparando exportação...". Also this
494	+  /// cubit's own initial state, since `export-summary-create`'s 202
495	+  /// response always answers `status: 'pending'` (`openapi.yaml`), so no
496	+  /// separate "creating..." state is needed before that call resolves.
497	+  const factory ExportJobState.preparing() = ExportJobPreparing;
498	+
499	+  /// `status in {processing, data_ready}` — progress bar, "Gerando resumo
500	+  /// com IA...". `data_ready` renders identically to `processing` here
501	+  /// (Design Notes/Never: lighting up its own download-enabled treatment
502	+  /// is Story 7.2's job).
503	+  const factory ExportJobState.generating() = ExportJobGenerating;
504	+
505	+  /// `status: 'done'` — [outcome] distinguishes "Concluído" (narrative
506	+  /// succeeded, both download buttons shown) from "Narrativa falhou/
507	+  /// pulada" (only the raw-data button, copy scoped to the narrative
508	+  /// failure) without needing two separate sealed variants for what is,
509	+  /// to the job itself, one and the same terminal success.
510	+  const factory ExportJobState.done(ExportOutcome outcome) = ExportJobDone;
511	+
