635	+/// The export feature's one port (RNF06) — `features/export/presentation`
636	+/// depends on this abstract class only, never `export/data` directly.
637	+/// Every method returns `Either<Failure, T>` (RNF09).
638	+abstract class ExportRepository {
639	+  /// Calls `export-summary-create` (`ApiClient.post`) — RF05's own job
640	+  /// kickoff for the period [periodStart]..[periodEnd]. Returns the
641	+  /// created job's `jobId` on success. `RetryInterceptor.
642	+  /// neverRetriedFunctions` already excludes this call from any
643	+  /// transparent retry (non-idempotent POST, no idempotency key) — every
644	+  /// [Failure] here, including a theoretical synchronous rejection,
645	+  /// propagates as `Left`, unmapped.
646	+  Future<Either<Failure, String>> createJob({
647	+    required DateTime periodStart,
648	+    required DateTime periodEnd,
649	+  });
650	+
651	+  /// Calls `export-status-get` (`ApiClient.get`, [jobId] appended as the
652	+  /// one trailing path segment) and maps the response straight into
653	+  /// [ExportJobState] — a thin pass-through, no cache (AD-15: ephemeral,
654	+  /// polled live). `Left` here is a transport-level failure only
655	+  /// (offline/timeout/malformed) — a backend-reported job failure
656	+  /// (including the empty-period case) already arrives as a
657	+  /// `Right(ExportJobState.error(...))`/`Right(ExportJobState.
658	+  /// emptyPeriod())`, never as a `Left`.
659	+  Future<Either<Failure, ExportJobState>> getStatus(String jobId);
